# ArticleCalendarSection (.html)

Use this article archive to browse months, filter articles by publication date, and paginate results. Do not embed it in individual articles.

**Semantic hints:** `calendar`, `schedule`, `dates`, `events-calendar`, `date-picker`, `archive`, `timeline`

## Configuration

Static HTML uses markup and script variables, not component props or imports.

| Setting | Type | Required / meaning |
|---|---|---|
| `title` | string | Yes; section heading |
| `articles` | Article[] | Yes; complete archive |
| `paginatedArticles` | Article[] | Yes; derived visible slice |
| `currentPage` | number | Yes; 1-based page |
| `totalPages` | number | Yes; derived page count |
| `pageSize` | number | Yes; articles per page |
| `paginationBasePath` | string | Yes; page link path |
| `id` | string | No; defaults to `calendar` |
| `paginationHash` | string | No; link fragment |
| `selectedDate` | Date | No; represented as `YYYY-MM-DD` |
| `onDateSelect` | function(Date) | No; optional date-click callback |

Article fields: `slug`, `title`, and ISO `date` are required strings; `description` and `image` are optional strings.

## Working example

```html
<!doctype html>
<html lang="en">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width">
<title>Article Archive</title>
<style>
.wrap{overflow:auto}
td,th{text-align:center}
[aria-selected=true] button{background:#154a85;color:white}
[aria-current=date]{border:2px solid}
</style>
<section id="calendar" aria-labelledby="heading">
<h2 id="heading">Article Archive</h2>
<button onclick="move(-1)">Previous month</button>
<span id="month" aria-live="polite"></span>
<button onclick="move(1)">Next month</button>
<button onclick="pick('')">All dates</button>
<div class="wrap">
<table role="grid" aria-labelledby="month">
<thead><tr><th>Sun<th>Mon<th>Tue<th>Wed<th>Thu<th>Fri<th>Sat</thead>
<tbody id="days"></tbody>
</table>
</div>
<div id="results" aria-live="polite"></div>
<nav id="pages" aria-label="Article pages"></nav>
</section>
<script>
const $=id=>document.getElementById(id), u=new URL(location.href),
a=['News','Notes','Review'].map((title,i)=>({
title,slug:'article-'+i,date:'2024-01-0'+(1+i)
}));
let d=u.searchParams.get('date')||'', m=new Date((u.searchParams.get('month')||d||'2024-01-01').slice(0,7)+'-01T00:00:00'),
p=+u.searchParams.get('page')||1;
function move(n){m.setMonth(m.getMonth()+n);draw()}
function pick(s){d=s;p=1;draw()}
function draw(){
const y=m.getFullYear(),k=m.getMonth(), key=y+'-'+String(k+1).padStart(2,'0');
$('month').textContent=m.toLocaleDateString('en',{month:'long',year:'numeric'});
$('days').innerHTML='';
let r;
for(let i=0;i<m.getDay()+new Date(y,k+1,0).getDate();i++){
if(i%7===0)r=$('days').insertRow();
const c=r.insertCell(),n=i-m.getDay()+1;
if(n<1)continue;
const s=key+'-'+String(n).padStart(2,'0'),b=document.createElement('button');
c.append(b);c.setAttribute('aria-selected',s===d);
b.textContent=n+(a.some(x=>x.date===s)?' •':'');
b.setAttribute('aria-label',s+(b.textContent.includes('•')?', articles available':''));
if(new Date(y,k,n).toDateString()===new Date().toDateString())b.setAttribute('aria-current','date');
b.onclick=()=>{pick(s);$('days').querySelector('[aria-selected=true] button').focus()};
}
const f=a.filter(x=>!d||x.date===d),t=Math.max(1,Math.ceil(f.length/2));
p=Math.min(t,Math.max(1,p));
$('results').innerHTML=f.slice(2*(p-1),2*p).map(x=>`<article><h3>${x.title}</h3><time>${x.date}</time></article>`).join('')||'No articles.';
$('pages').replaceChildren(`Page ${p} of ${t} `);
for(const [label,n] of [['Previous',p-1],['Next',p+1]])if(n>0&&n<=t){
const l=document.createElement('a');
l.href='?'+new URLSearchParams({month:key,date:d,page:n})+'#calendar';
l.textContent=label;$('pages').append(l,' ');
}}
draw();
</script>
```

